SourceCode.Declaration:
/// <summary>
/// The warehouses one handheld user is allowed to work in.
///
/// A worker is rarely tied to exactly one warehouse for ever - cover for a sick colleague, a
/// second site down the road, a peak-season move - so the assignment is a list, with one row
/// marked default. The app signs the worker straight into the default and offers the rest as a
/// switch, which means nobody types a warehouse code at a receiving bay and nobody can pick a
/// warehouse they have no business in.
///
/// This is also the reason the free-text warehouse box in the app's settings stops being the
/// source of truth once a worker signs in: a typo there previously produced an empty worklist
/// that looked exactly like a broken app.
/// </summary>
public class HSMobileOpsUserWarehouse extends common
{
}

Method.Source:
/// <summary>
/// Unsets the default flag on every row for a user, except optionally one to keep.
///
/// Enforced here rather than trusted to callers. Two rows marked default is a state with no
/// correct interpretation - the app would pick whichever the query happened to return first,
/// and the same worker would land in different warehouses on different days.
/// </summary>
public static void clearDefaults(RefRecId _userRecId, RefRecId _keepRecId = 0)
{
    HSMobileOpsUserWarehouse assignment;

    update_recordset assignment
        setting IsDefault = NoYes::No
        where assignment.UserRecId  == _userRecId
           && assignment.IsDefault  == NoYes::Yes
           && assignment.RecId      != _keepRecId;
}

/// <summary>
/// The user's default warehouse assignment, or their only one if none is flagged.
///
/// Falling back to a single unflagged assignment rather than returning nothing: a user with
/// exactly one warehouse and nobody having ticked the box is an administrative slip, not a
/// reason to refuse them a shift.
/// </summary>
public static HSMobileOpsUserWarehouse findDefault(RefRecId _userRecId)
{
    HSMobileOpsUserWarehouse assignment;
    int                      assignmentCount;

    select firstOnly assignment
        where assignment.UserRecId == _userRecId
           && assignment.IsDefault == NoYes::Yes;

    if (assignment.RecId)
    {
        return assignment;
    }

    select count(RecId) from assignment
        where assignment.UserRecId == _userRecId;

    if (any2Int(assignment.RecId) == 1)
    {
        select firstOnly assignment
            where assignment.UserRecId == _userRecId;
    }
    else
    {
        assignment.clear();
    }

    return assignment;
}
